#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_foreach_tanh.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

// Helper: flatten TensorList to a single contiguous tensor
torch::Tensor _flatten_tensor_list(const at::TensorList &tensors)
{
    if (tensors.size() == 0) {
        return at::empty({0}, tensors[0].options());
    }

    // Check all tensors have the same dtype and device
    auto dtype = tensors[0].scalar_type();
    auto device = tensors[0].device();
    for (size_t i = 1; i < tensors.size(); ++i) {
        TORCH_CHECK(tensors[i].scalar_type() == dtype,
                    "foreach_tanh: all tensors must have the same dtype");
        TORCH_CHECK(tensors[i].device() == device,
                    "foreach_tanh: all tensors must be on the same device");
    }

    // Calculate total number of elements
    int64_t totalElements = 0;
    for (const auto &t : tensors) {
        totalElements += t.numel();
    }

    if (totalElements == 0) {
        return at::empty({0}, tensors[0].options());
    }

    // Create a flat tensor and copy data
    auto flat = at::empty({totalElements}, tensors[0].options());
    int64_t offset = 0;
    for (const auto &t : tensors) {
        if (t.numel() > 0) {
            flat.narrow(0, offset, t.numel()).copy_(t.view(-1));
            offset += t.numel();
        }
    }

    return flat;
}

// Helper: split flat tensor back to list of tensors with original shapes
std::vector<at::Tensor> _unflatten_tensor(const at::Tensor &flat,
                                           const std::vector<std::vector<int64_t>> &shapes)
{
    std::vector<at::Tensor> results;
    int64_t offset = 0;
    for (const auto &shape : shapes) {
        int64_t numel = 1;
        for (auto dim : shape) {
            numel *= dim;
        }
        auto t = flat.narrow(0, offset, numel).view(shape).clone();
        results.push_back(t);
        offset += numel;
    }
    return results;
}

at::TensorList foreach_tanh(const at::TensorList &inputs)
{
    // ---- Input validation ----
    TORCH_CHECK(inputs.size() > 0, "foreach_tanh: input list must not be empty");

    auto dtype = inputs[0].scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kBFloat16 || dtype == at::kFloat,
                "foreach_tanh: only float16, bfloat16 and float32 are supported, got ", dtype);

    // ---- Flatten inputs to a single tensor ----
    auto flatInput = _flatten_tensor_list(inputs);
    int64_t totalLength = flatInput.numel();

    if (totalLength == 0) {
        std::vector<at::Tensor> emptyResults;
        for (size_t i = 0; i < inputs.size(); ++i) {
            emptyResults.push_back(at::empty_like(inputs[i]));
        }
        return at::TensorList(emptyResults);
    }

    auto flatOutput = at::empty_like(flatInput);
    int64_t dtypeSize = flatInput.element_size();

    // ---- Get hardware params ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block level tiling (inter-core split, Cache Line aligned) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB level tiling (intra-core split) ----
    // bufferCoefficient from UB allocation table:
    // float32: 20 (2 queues * 2 double buf * 4B + 1 temp * 4B = 20)
    // float16/bfloat16: 16 (2 queues * 2 double buf * 2B + 2 temp * 4B = 16)
    int64_t bufferCoefficient;
    if (dtypeSize == 4) {
        bufferCoefficient = 20;
    } else {
        bufferCoefficient = 16;
    }

    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- Launch kernel ----
    // All params must be lvalues
    int64_t formerNumLval = formerNum;
    int64_t formerLengthLval = formerLength;
    int64_t tailLengthLval = tailLength;
    int64_t tileLengthLval = tileLength;
    int64_t dtypeSizeLval = dtypeSize;

    EXEC_KERNEL_CMD(foreach_tanh, blockDim,
                    flatInput, flatOutput,
                    formerNumLval, formerLengthLval, tailLengthLval,
                    tileLengthLval, dtypeSizeLval);

    // ---- Split output back to tensor list ----
    std::vector<std::vector<int64_t>> shapes;
    for (const auto &t : inputs) {
        shapes.push_back(t.sizes().vec());
    }
    auto results = _unflatten_tensor(flatOutput, shapes);

    // Return as TensorList
    static thread_local std::vector<at::Tensor> resultStorage;
    resultStorage = std::move(results);
    return at::TensorList(resultStorage);
}

}  // namespace ascend_kernel
