18	
19	// Helper: flatten TensorList to a single contiguous tensor
20	torch::Tensor _flatten_tensor_list(const at::TensorList &tensors)
21	{
22	    if (tensors.size() == 0) {
23	        return at::empty({0}, tensors[0].options());
24	    }
25	
26	    // Check all tensors have the same dtype and device
27	    auto dtype = tensors[0].scalar_type();
28	    auto device = tensors[0].device();
29	    for (size_t i = 1; i < tensors.size(); ++i) {
30	        TORCH_CHECK(tensors[i].scalar_type() == dtype,
31	                    "foreach_tanh: all tensors must have the same dtype");
32	        TORCH_CHECK(tensors[i].device() == device,
33	                    "foreach_tanh: all tensors must be on the same device");
34	    }
35	
36	    // Calculate total number of elements
37	    int64_t totalElements = 0;
38	    for (const auto &t : tensors) {
39	        totalElements += t.numel();
40	    }
41	
42	    if (totalElements == 0) {
43	        return at::empty({0}, tensors[0].options());
44	    }
45	
46	    // Create a flat tensor and copy data
47	    auto flat = at::empty({totalElements}, tensors[0].options());
48	    int64_t offset = 0;
49	    for (const auto &t : tensors) {
50	        if (t.numel() > 0) {
51	            flat.narrow(0, offset, t.numel()).copy_(t.view(-1));
52	            offset += t.numel();
53	        }
54	    }
55	
56	    return flat;
57	}
58	
59	// Helper: split flat tensor back to list of tensors with original shapes
60	std::vector<at::Tensor> _unflatten_tensor(const at::Tensor &flat,
61	                                           const std::vector<std::vector<int64_t>> &shapes)
62	{
63	    std::vector<at::Tensor> results;
64	    int64_t offset = 0;
65	    for (const auto &shape : shapes) {
66	        int64_t numel = 1;
67	        for (auto dim : shape) {
68	            numel *= dim;
69	        }
70	        auto t = flat.narrow(0, offset, numel).view(shape).clone();
71	        results.push_back(t);
72	        offset += numel;
73	    }
74	    return results;
75	}
76	
77	at::TensorList foreach_tanh(const at::TensorList &inputs)
78	{
79	    // ---- Input validation ----
80	    TORCH_CHECK(inputs.size() > 0, "foreach_tanh: input list must not be empty");
81	
82	    auto dtype = inputs[0].scalar_type();
83	    TORCH_CHECK(dtype == at::kHalf || dtype == at::kBFloat16 || dtype == at::kFloat,
84	                "foreach_tanh: only float16, bfloat16 and float32 are supported, got ", dtype);
85	
86	    // ---- Flatten inputs to a single tensor ----
87	    auto flatInput = _flatten_tensor_list(inputs);
88	    int64_t totalLength = flatInput.numel();
89	
90	    if (totalLength == 0) {
91	        std::vector<at::Tensor> emptyResults;
92	        for (size_t i = 0; i < inputs.size(); ++i) {
93	            emptyResults.push_back(at::empty_like(inputs[i]));
94	        }
95	        return at::TensorList(emptyResults);
96	    }
97	
98	    auto flatOutput = at::empty_like(flatInput);
99	    int64_t dtypeSize = flatInput.element_size();
100	
101	    // ---- Get hardware params ----
102	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
103	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
104	    uint64_t ubSize;
105	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
106	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
107	
108	    // ---- Block level tiling (inter-core split, Cache Line aligned) ----
109	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
110	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
111	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
112	
113	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
114	    int64_t formerNum = usedCoreNum - 1;
115	    int64_t formerLength = totalLengthCoreAlign;
116	    int64_t tailLength = totalLength - formerNum * formerLength;
117	
118	    // ---- UB level tiling (intra-core split) ----
119	    // bufferCoefficient from UB allocation table:
120	    // float32: 20 (2 queues * 2 double buf * 4B + 1 temp * 4B = 20)
