#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_foreach_tanh.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::TensorList foreach_tanh(const at::TensorList &inputs)
{
    TORCH_CHECK(inputs.size() > 0, "foreach_tanh: input list must not be empty");

    auto dtype = inputs[0].scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kBFloat16 || dtype == at::kFloat,
                "foreach_tanh: only float16, bfloat16 and float32 are supported, got ", dtype);

    int64_t totalLength = 0;
    for (const auto &t : inputs) {
        totalLength += t.numel();
    }

    std::vector<at::Tensor> outputs;
    for (const auto &t : inputs) {
        outputs.push_back(at::empty_like(t));
    }

    if (totalLength == 0) {
        static thread_local std::vector<at::Tensor> emptyResultStorage;
        emptyResultStorage = std::move(outputs);
        return at::TensorList(emptyResultStorage);
    }

    auto flatInput = at::empty({totalLength}, inputs[0].options());
    auto flatOutput = at::empty({totalLength}, inputs[0].options());

    int64_t offset = 0;
    for (const auto &t : inputs) {
        if (t.numel() > 0) {
            flatInput.narrow(0, offset, t.numel()).copy_(t.reshape({-1}));
            offset += t.numel();
        }
    }

    int64_t dtypeSize = flatInput.element_size();

    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    int64_t formerNumLval = formerNum;
    int64_t formerLengthLval = formerLength;
    int64_t tailLengthLval = tailLength;
    int64_t tileLengthLval = tileLength;
    int64_t dtypeSizeLval = dtypeSize;

    EXEC_KERNEL_CMD(foreach_tanh, blockDim,
                    flatInput, flatOutput,
                    formerNumLval, formerLengthLval, tailLengthLval,
                    tileLengthLval, dtypeSizeLval);

    offset = 0;
    for (size_t i = 0; i < inputs.size(); ++i) {
        if (inputs[i].numel() > 0) {
            outputs[i].copy_(flatOutput.narrow(0, offset, inputs[i].numel()).reshape(inputs[i].sizes()));
            offset += inputs[i].numel();
        }
    }

    static thread_local std::vector<at::Tensor> resultStorage;
    resultStorage = std::move(outputs);
    return at::TensorList(resultStorage);
}

}  // namespace ascend_kernel
