            auto out_slice = flatOutput.narrow(0, offset, inputs[i].numel()).reshape(inputs[i].sizes());
            if (isBf16) {
                outputs[i].copy_(out_slice.to(at::kBFloat16));
            } else {
                outputs[i].copy_(out_slice);
            }
            offset += inputs[i].numel();
        }
    }

    static thread_local std::vector<at::Tensor> resultStorage;
    resultStorage = std::move(outputs);
    return at::TensorList(resultStorage);
}

